/* Admin-only organization and report review, sharing the existing mint workspace. */
bossPages.find(p=>p[0]==='people')[2]='部门与人员';
bossPages.find(p=>p[0]==='audit')[2]='报送核查';
bossPages.splice(1,0,['statistics','layers','数据统计']);
bossPages.splice(bossPages.findIndex(p=>p[0]==='audit'),0,['unreported','users','每日报送进度']);
opsTitles.statistics=['作品表现，单独查看。','按时间、部门和人员查看互动数据，以及员工、小组排行榜。'];
opsTitles.missing=['核对已发布作品的报送情况。','查看待提交、逾期和待确认作品，记录处理原因。'];
opsTitles.unreported=['查看每天的要求、完成数和差额。','按作品发布时间统计有效作品，跟进未完成与待处理的报送。'];
opsTitles.people=['人员有归属，报送更省心。','补齐部门名册，才能核对从未报送的人员；员工首次报送也可自动建档。'];
opsTitles.audit=['员工报送，集中核实。','查看报送、作者核验和员工备注，处理归属异常或识别失败。'];
opsTitles.overview=['查看今日报送进度，','及时跟进未完成的人员与待处理作品。'];
const reportAdmin={filters:{},page:1,result:null,selected:new Set(),peopleSearch:'',peopleStatus:'all',load:0};
const reportStateNames={queued:'等待识别',processing:'正在识别',submitted:'已报送',review:'待核实',failed:'处理失败',duplicate:'重复报送',rejected:'未通过'};
const progressNames={missing:'未报送',reported:'已报送',attention:'报送待处理',excused:'无需报送'};
function reportProgressNames(){return ops.data.progress?.quota_mode?{missing:'未完成',reported:'已完成',attention:'未完成 · 待处理',excused:'无需报送'}:progressNames}
function reportProgressCards(){const r=ops.data.progress;if(!r)return '';return `<section class="panel report-progress-summary"><div class="panel-header"><span class="panel-title">${esc(r.date)} · 人员报送进度</span><small class="subtle">在册 ${r.counts.total} 人${r.quota_mode?' · 截止 '+esc(r.rule.cutoff):' · 历史接收记录'}</small></div><div class="report-progress-cards">${Object.entries(reportProgressNames()).map(([key,label])=>`<button class="${key==='missing'&&r.counts[key]?'needs-attention':''}" data-progress-status="${key}"><span>${label}</span><strong>${r.counts[key]} <small>人</small></strong></button>`).join('')}</div></section>`}
function reportDailyStatus(u){return u.status==='excused'?'无需报送':u.status==='reported'?(u.late_count?'已完成 · 含补报':'已完成'):u.phase==='overdue'?'未达标':'进行中'}
function reportProgressPage(){const r=ops.data.progress,p=ops.data.people,f=ops.filters,names=reportProgressNames(),quota=r.quota_mode;return `${reportProgressCards()}<section class="panel"><form id="ops-filter" class="panel-body ops-filters"><div class="field"><label for="progress-date">${quota?'作品发布日期':'报送日期'}（北京时间）</label><input type="date" name="date" id="progress-date" value="${esc(r.date)}" max="${new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}" required></div>${reportDeptField()}<div class="field"><label for="progress-group">小组</label><select id="progress-group" name="group">${opsOpts(p.groups,'id','name',f.group)}</select></div><div class="field"><label for="progress-employee">员工</label><select id="progress-employee" name="employee">${opsOpts(p.users.filter(u=>u.role==='employee'&&u.enabled&&!u.deleted_at),'id','name',f.employee)}</select></div><div class="field"><label for="progress-status">完成状态</label><select id="progress-status" name="status"><option value="all" ${f.status==='all'?'selected':''}>全部人员</option>${Object.entries(names).map(([key,label])=>`<option value="${key}" ${(f.status||'missing')===key?'selected':''}>${label}</option>`).join('')}</select></div><div class="field"><label for="progress-search">姓名 / 工号</label><input name="search" id="progress-search" value="${esc(f.search||'')}" placeholder="输入姓名或工号"></div><div class="ops-filter-actions"><button type="submit" class="primary">查询</button><button type="button" class="secondary" id="ops-filter-reset">返回今天</button></div></form></section><section class="panel"><div class="panel-header report-admin-header"><span class="panel-title">${names[f.status||'missing']||'全部人员'} <small class="subtle">${r.total} 人</small></span><div class="report-admin-actions"><button class="text-button" data-daily-open-rules>设置每日要求</button><a class="link-inline" href="/api/ops/report-progress/export?${esc(new URLSearchParams({...f,date:r.date}).toString())}" download>导出 Excel</a><button class="text-button" id="ops-reload">刷新</button></div></div><div class="panel-body report-progress-help"><p>${quota?'有效完成只计算已审核归属、且在所选日期发布的不同作品；重复报送不增加完成数。截止前显示进行中，截止后仍不足显示未达标。':'该日期尚未启用每日目标，保留原接收记录口径：按网站当天收到的报送核对，不代表当天发布量。'}</p><details class="workspace-details"><summary>统计范围与人员名册</summary><p>核对范围为当日已建档、当前启用的员工。请先补齐完整名册，才能发现从未报送过的人。<button class="text-button" data-report-person-new>添加人员</button><button class="text-button" data-report-import>批量导入名册</button></p><p>补交昨天发布的作品归入昨天；审核晚于截止时间不会改变原接收时间。失败、待核实或未通过的作品不计有效完成；发布时间未识别的记录仅提示，不能算作当日作品。未完成仅表示网站的有效记录不足，不能证明员工没有发布。</p></details></div><div class="ops-table-wrap"><table class="ops-table report-progress-table"><thead><tr><th>员工</th><th>部门 / 小组</th><th>${quota?'要求 / 有效完成':'当日报送'}</th><th>${quota?'待处理 / 待识别':'最近报送时间'}</th><th>状态 / 原因</th><th>操作</th></tr></thead><tbody>${r.items.map(u=>`<tr><td><b>${esc(u.name)}</b><small>${esc(u.employee_code)}</small></td><td>${esc(u.department_name)}<small>${esc(u.group_name)}</small></td><td>${quota?`<div class="daily-quota-value"><b>${u.completed_count}</b><span>/ ${u.required} 条</span></div><small>${u.required?'还差 '+u.remaining+' 条':'当日免报'} · ${esc(u.excuse?'管理员免报':u.target.source)}</small>${u.late_count?`<small>含补报 ${u.late_count} 条</small>`:''}`:`${u.received_count} 条<small>已归档 ${u.accepted_count} · 待处理 ${u.attention_count}</small>`}</td><td>${quota?`${u.pending_count} 条待处理<small>发布时间待识别 ${u.unlocated_count} 条</small>`:u.last_received?opsDate(u.last_received):'暂无报送记录'}</td><td><span class="status-chip ${u.status==='reported'?'ok':''}">${quota?reportDailyStatus(u):names[u.status]}</span>${quota&&u.status==='attention'?'<small>需要跟进报送处理</small>':''}${u.excuse?`<small>${esc(u.excuse)}</small>`:quota&&u.target.note?`<small>${esc(u.target.note)}</small>`:''}</td><td><div class="report-admin-actions">${quota?`<button class="text-button" data-daily-works="${esc(u.id)}">查看作品</button>`:''}<button class="text-button" data-progress-reports="${esc(u.id)}">查看报送</button><button class="text-button" data-daily-employee="${esc(u.id)}">个人要求</button><button class="text-button" data-progress-excuse="${esc(u.id)}">${u.excuse?'调整免报':'无需报送'}</button></div></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty-state">当前筛选没有匹配人员。可切换状态、日期，或补齐员工名册。</div></td></tr>'}</tbody></table></div><div class="log-pagination ops-pages"><button class="secondary" id="ops-prev" ${r.page<=1?'disabled':''}>上一页</button><span>共 ${r.total} 人 · 第 ${r.page} / ${Math.max(1,Math.ceil(r.total/30))} 页</span><button class="secondary" id="ops-next" ${r.page*30>=r.total?'disabled':''}>下一页</button></div></section>`}

function reportTimingRules(){const s=ops.data.settings;return `<section class="panel"><div class="panel-header"><span class="panel-title">报送规则</span></div><form id="ops-settings-form" class="panel-body"><div class="form-grid">${[['deadline_hours','发布后报送时限（小时）',1,720],['retry_limit','识别 / 刷新失败重试次数',0,5],['retry_minutes','失败重试间隔（分钟）',1,1440]].map(([key,label,min,max])=>`<div class="field"><label for="${key}">${label}</label><input name="${key}" id="${key}" type="number" value="${s[key]}" min="${min}" max="${max}" required></div>`).join('')}</div><p class="subtle ops-footnote">报送时限用于比较作品发布时间与收到报送的时间。每日报送进度按有效作品和目标条数核对；每日截止时间与此处的发布后时限分别计算。请假、休息可在对应日期备注“无需报送”。系统不再自动读取账号发布列表。</p><button type="submit" class="primary">保存报送规则</button></form></section>`}
function reportProgressExcuse(id){const r=ops.data.progress,u=r.items.find(u=>u.id===id);if(!u)return;opsModal('当日报送要求',`<form id="progress-excuse-form"><p>${esc(u.name)} · ${esc(r.date)}</p><label class="ops-checkbox"><input name="enabled" type="checkbox" checked>当日无需报送</label><div class="field"><label for="progress-excuse-reason">原因</label><textarea id="progress-excuse-reason" name="reason" maxlength="500" placeholder="例如：请假、休息日、当日无报送安排">${esc(u.excuse||'')}</textarea></div><p class="subtle ops-footnote">仅调整这一天的报送要求，保留已收到的报送与操作日志。取消勾选可恢复正常核对。</p><p class="ops-form-error" id="progress-excuse-error" role="alert"></p><button class="primary" type="submit">保存</button></form>`);document.querySelector('#progress-excuse-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{await post('/ops/report-progress/excuse',{date:r.date,employee:id,enabled:e.target.elements.enabled.checked,reason:e.target.elements.reason.value});document.querySelector('#detail-dialog').close();await loadOps();toast('当日报送要求已保存')}catch(err){document.querySelector('#progress-excuse-error').textContent=err.message}finally{button.disabled=false}}}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||ops.user?.role!=='admin')return;if(b.dataset.progressStatus){const f=state.page==='overview'?{department:ops.filters.department||'',group:ops.filters.group||'',employee:ops.filters.employee||''}:ops.filters;opsOpen('unreported',{...f,date:ops.data.progress.date,status:b.dataset.progressStatus})}if(b.dataset.progressReports){reportAdmin.filters={employee:b.dataset.progressReports,...(ops.data.progress.quota_mode?{}:{date:ops.data.progress.date})};reportAdmin.page=1;opsOpen('audit',{})}if(b.dataset.progressExcuse)reportProgressExcuse(b.dataset.progressExcuse)});
let opsActiveSearch=null;
function opsCloseSearch(){if(opsActiveSearch){opsActiveSearch.close();opsActiveSearch=null}}
function opsBindSearchFilters(){
  if(opsActiveSearch&&!opsActiveSearch.input.isConnected)opsCloseSearch();
  if(!document.querySelectorAll)return;
  document.querySelectorAll('#ops-filter select,#report-queue-filter select,#progress-search').forEach(select=>{
    const freeText=select.id==='progress-search';
    if((!freeText&&!['department','employee','group','binding'].includes(select.name))||select.dataset.searchReady)return;
    select.dataset.searchReady='1';
    const field=select.closest('.field'),label=field.querySelector('label'),title=label?.textContent||'筛选';
    const wrapper=document.createElement('div');wrapper.className='ops-search-select';
    const input=freeText?select:document.createElement('input');input.type='text';if(!freeText)input.id=select.id+'-search';
    input.autocomplete='off';input.placeholder='输入'+title+'搜索';input.setAttribute('role','combobox');
    input.setAttribute('aria-autocomplete','list');input.setAttribute('aria-expanded','false');
    const toggle=document.createElement('button');toggle.type='button';toggle.className='ops-search-toggle';
    toggle.textContent='⌄';toggle.tabIndex=-1;toggle.setAttribute('aria-label','展开'+title+'选项');
    const list=document.createElement('div');list.className='ops-search-options';list.id=input.id+'-options';
    list.setAttribute('role','listbox');list.setAttribute('aria-label',title+'匹配项');list.hidden=true;
    input.setAttribute('aria-controls',list.id);
    select.before(wrapper);wrapper.append(input,toggle);if(!freeText){select.hidden=true;select.tabIndex=-1;}
    if(label)label.htmlFor=input.id;
    let matches=[],active=-1;
    const selected=()=>freeText?input.value:select.selectedOptions[0]?.textContent||'全部';
    input.value=selected();
    function detail(option){
      if(!option.value)return '清除当前筛选';
      const p=ops.data.people,groups=p?.groups||[],departments=p?.departments||[];
      if(freeText||select.name==='employee'){
        const user=p?.users.find(u=>u.id===(option.userId||option.value)),group=groups.find(g=>g.id===user?.group_id);
        return [departments.find(d=>d.id===group?.department_id)?.name,group?.name,user?.employee_code?'工号 '+user.employee_code:''].filter(Boolean).join(' / ');
      }
      if(select.name==='group'){const g=groups.find(g=>g.id===option.value);return departments.find(d=>d.id===g?.department_id)?.name||''}
      if(select.name==='binding'){const b=ops.data.bindings.find(b=>b.id===option.value);return [b?.employee_name,b?.uid?'UID '+b.uid:b?.sec_uid].filter(Boolean).join(' / ')}
      return '';
    }
    function position(){
      if(!input.isConnected){opsCloseSearch();return}
      const r=input.getBoundingClientRect(),below=window.innerHeight-r.bottom-10,above=r.top-10;
      const height=Math.min(260,Math.max(80,Math.max(below,above)));
      list.style.width=r.width+'px';list.style.left=r.left+'px';list.style.maxHeight=height+'px';
      list.style.top=below>=Math.min(180,above)?r.bottom+5+'px':'auto';
      list.style.bottom=list.style.top==='auto'?window.innerHeight-r.top+5+'px':'auto';
    }
    function close(){list.hidden=true;list.remove();input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');active=-1}
    function choose(option){
      if(freeText){input.value=option.value;input.setCustomValidity('');opsCloseSearch();return;}
      select.value=option.value;input.value=option.textContent;input.setCustomValidity('');
      select.dispatchEvent(new Event('change',{bubbles:true}));opsCloseSearch();
    }
    function mark(index){
      active=index;Array.from(list.querySelectorAll('[role=option]')).forEach((el,i)=>el.setAttribute('aria-selected',String(i===active)));
      const option=list.children[index];if(option){input.setAttribute('aria-activedescendant',option.id);option.scrollIntoView({block:'nearest'})}
    }
    function open(){
      if(opsActiveSearch?.input!==input){opsCloseSearch();opsActiveSearch={input,wrapper,list,close,position}}
      const query=!freeText&&input.value===selected()?'':input.value.trim().toLocaleLowerCase();
      let options=freeText?[]:Array.from(select.options);
      if(freeText){
        const p=ops.data.people,form=input.closest('form');
        const department=form.elements.department?.value,group=form.elements.group?.value,employee=form.elements.employee?.value;
        options=(p?.users||[]).filter(u=>u.role==='employee'&&u.enabled&&!u.deleted_at&&
          (!employee||u.id===employee)&&(!group||u.group_id===group)&&
          (!department||(p.groups||[]).find(g=>g.id===u.group_id)?.department_id===department))
          .map(u=>({value:u.employee_code||u.name,textContent:u.name,userId:u.id}));
      }
      matches=options.filter(option=>!option.disabled&&(!query||(option.textContent+' '+detail(option)).toLocaleLowerCase().includes(query)));
      list.replaceChildren();active=-1;input.removeAttribute('aria-activedescendant');
      for(const [index,option] of matches.entries()){
        const button=document.createElement('button');button.type='button';button.tabIndex=-1;button.id=list.id+'-'+index;
        button.setAttribute('role','option');button.setAttribute('aria-selected','false');
        const name=document.createElement('span');name.textContent=option.textContent;button.append(name);
        const note=detail(option);if(note){const small=document.createElement('small');small.textContent=note;button.append(small)}
        button.addEventListener('mousedown',event=>event.preventDefault());
        button.addEventListener('click',()=>{choose(option);input.focus()});list.append(button);
      }
      if(!matches.length){const empty=document.createElement('div');empty.className='ops-search-empty';empty.textContent='没有匹配项，请调整关键词';empty.setAttribute('role','status');list.append(empty)}
      document.body.append(list);list.hidden=false;input.setAttribute('aria-expanded','true');position();
    }
    input.addEventListener('focus',()=>{input.select();open()});input.addEventListener('click',open);
    input.addEventListener('input',()=>{
      if(freeText)input.setCustomValidity('');
      else if(!input.value.trim()){select.value='';input.setCustomValidity('')}
      else input.setCustomValidity(input.value===selected()?'':'请从下方提示中选择'+title);
      open();
    });
    input.addEventListener('change',()=>{
      if(freeText)return;
      const exact=Array.from(select.options).filter(o=>o.textContent===input.value.trim());
      if(exact.length===1){select.value=exact[0].value;input.setCustomValidity('')}
    });
    input.addEventListener('keydown',event=>{
      if(event.isComposing)return;
      if(['ArrowDown','ArrowUp'].includes(event.key)){event.preventDefault();if(list.hidden)open();if(matches.length)mark((active+(event.key==='ArrowDown'?1:active<0?0:-1)+matches.length)%matches.length)}
      if(event.key==='Enter'&&!list.hidden&&active>=0){event.preventDefault();choose(matches[active])}
      if(event.key==='Escape'){event.preventDefault();opsCloseSearch()}
      if(event.key==='Tab')opsCloseSearch();
    });
    toggle.addEventListener('mousedown',event=>event.preventDefault());
    toggle.addEventListener('click',()=>{if(opsActiveSearch?.input===input)opsCloseSearch();else{input.focus();open()}});
    input.addEventListener('blur',()=>{if(opsActiveSearch?.input===input)opsCloseSearch()});
    if(!freeText)select.addEventListener('change',()=>{input.value=selected();input.setCustomValidity('')});
  });
}
document.addEventListener('pointerdown',event=>{if(opsActiveSearch&&!opsActiveSearch.wrapper.contains(event.target)&&!opsActiveSearch.list.contains(event.target))opsCloseSearch()});
document.addEventListener('scroll',()=>opsActiveSearch?.position(),true);
window.addEventListener('resize',()=>opsActiveSearch?.position());
window.addEventListener('hashchange',opsCloseSearch);
const reportingBaseAuth=renderOpsAuth,reportingBaseProfile=opsProfile,reportingBaseLoad=loadOps,reportingBaseSettings=opsSettings,reportingBaseFilter=opsFilter,reportingBaseScope=opsScopeFilter,reportingBaseEditor=opsEditor;
bootstrapOps=async function(){
  try{const data=await api('/auth/status');ops.initialized=data.initialized;ops.user=data.user?.role==='admin'?data.user:null;ops.ready=true;
    if(!ops.user&&!location.pathname.startsWith('/admin')&&location.hash!=='#login'){location.replace('/report');return}
    if(['checks','missing'].includes(state.page)){state.page='unreported';history.replaceState(null,'','#unreported')}
    if(ops.user&&!bossPages.some(p=>p[0]===state.page)){state.page='overview';history.replaceState(null,'','#overview')}
    render();
  }catch{ops.ready=true;document.querySelector('#content').innerHTML='<section class="panel"><div class="panel-body report-admin-error">服务暂时不可用，请确认服务器已启动后刷新页面。</div></section>'}
};
renderOpsAuth=function(){reportingBaseAuth();if(!ops.ready)return;document.querySelector('#breadcrumb').textContent='管理入口';const intro=document.querySelector('.page-heading p');if(intro)intro.textContent=ops.initialized?'使用管理员账号管理部门作品与报送情况。':'设置管理员账号，即可查看员工报送并管理部门台账。';document.querySelector('#ops-auth-form')?.insertAdjacentHTML('beforeend','<p class="report-auth-link">员工无需登录，<a class="link-inline" href="/report">前往作品报送 ↗</a></p>');};
opsProfile=function(){document.querySelectorAll('.report-public-entry').forEach(el=>el.remove());reportingBaseProfile();document.querySelector('.workspace small').textContent='部门、作品与报送管理';const badge=document.querySelector('.local-badge');if(badge)badge.innerHTML='<span class="online-dot"></span>部门工作台';if(ops.user){document.querySelector('.sidebar-bottom .profile')?.insertAdjacentHTML('beforebegin','<a class="nav-item report-public-entry" href="/report" target="_blank" rel="noreferrer">'+icon('external')+'员工报送入口 ↗</a>');hydrate()}};
function reportDeptField(){const p=ops.data.people;return p?`<div class="field"><label for="report-filter-department">部门</label><select name="department" id="report-filter-department">${opsOpts(p.departments||[],'id','name',ops.filters.department)}</select></div>`:''}
function reportEmployeeFilters(html){return html.replace(/<select([^>]*\bname="employee"[^>]*)>[\s\S]*?<\/select>/g,(_,attributes)=>`<select${attributes}>${opsOpts((ops.data.people?.users||[]).filter(user=>user.role==='employee'),'id','name',ops.filters.employee)}</select>`)}
opsFilter=function(){
  const expanded=['state','search','sort','order'].some(key=>ops.filters[key]);
  let html=reportingBaseFilter().replace('<form class="ops-filters" id="ops-filter">','<form class="ops-filters" id="ops-filter">'+reportDeptField());
  html=html.replace('<div class="field"><label for="ops-state">',`<details class="workspace-advanced" ${expanded?'open':''}><summary>更多筛选 <span>状态、排序、作品关键词</span></summary><div class="workspace-advanced-grid"><div class="field"><label for="ops-state">`);
  html=html.replace('<div class="ops-filter-actions">','</div></details><div class="ops-filter-actions">');
  return reportEmployeeFilters(html);
};
opsScopeFilter=function(){return reportEmployeeFilters(reportingBaseScope().replace('<form id="ops-filter" class="ops-filters">','<form id="ops-filter" class="ops-filters">'+reportDeptField()))};
opsSummary=function(){const s=ops.data.summary;return `<div class="stat-grid ops-stats">${opsStat('已收录作品',s.works,'按下方作品发布时间与归属筛选','video')}${opsStat('已归档报送',s.submitted,'作品归属已确认','check')}${opsStat('迟报记录',s.late_submissions,'比较作品发布时间与首次有效报送时间','clock')}</div>`};
function opsOverviewSummary(){
  const s=ops.data.summary;
  return `<div class="overview-work-metrics">${[
    ['已收录作品',s.works,'已保存的作品记录','件'],
    ['已归档报送',s.submitted,'作品归属已确认','件'],
    ['迟报记录',s.late_submissions,'超过发布后报送时限','条']
  ].map(([label,value,note,unit])=>`<div><span>${label}</span><strong>${opsNumber(value)}<small>${unit}</small></strong><p>${note}</p></div>`).join('')}</div>`;
}
function reportOverviewScope(){
  const p=ops.data.people,f=ops.filters,labels=[];
  for(const [key,items] of [['department',p.departments||[]],['group',p.groups],['employee',p.users]]){
    if(f[key])labels.push(items.find(item=>item.id===f[key])?.name||'已选人员范围');
  }
  return labels.join(' / ')||'全部部门与人员';
}
function reportOverviewPage(){
  const r=ops.data.progress,c=r.counts,f=ops.filters;
  const active=Object.values(f).some(value=>value&&value!=='all');
  const dates=[f.start?opsFilterTime(f.start).replace('T',' '):'不限起始',f.end?opsFilterTime(f.end,true).replace('T',' '):'至今'];
  const timeScope=f.start||f.end?dates.join(' — '):'全部发布时间';
  const account=f.binding?ops.data.bindings.find(b=>b.id===f.binding)?.nickname||'已选账号':'全部抖音账号';
  return `<div class="overview-dashboard">
    <div class="overview-toolbar"><span>${icon('users')}${esc(reportOverviewScope())}</span><button class="text-button" id="ops-reload">${icon('refresh')}刷新数据</button></div>
    <div class="overview-top-grid">
      <section class="overview-card overview-people" aria-labelledby="overview-people-title">
        <div class="overview-card-head"><div><h2 id="overview-people-title">今日人员报送进度</h2><p>${r.quota_mode?'按今日发布的有效作品统计 · 截止 '+esc(r.rule.cutoff):'按今日收到的报送统计 · 北京时间'}</p></div><span class="overview-roster-total">在册 <b>${c.total}</b> 人</span></div>
        <div class="overview-person-metrics">${[
          ['missing',r.quota_mode?'未完成':'未报送','查看需要提醒的人员'],['reported',r.quota_mode?'已完成':'已报送','查看已完成的人员'],
          ['attention',r.quota_mode?'未完成 · 待处理':'报送待处理','查看需要跟进的人员'],['excused','无需报送','查看当日免报人员']
        ].map(([key,label,hint])=>`<button type="button" class="overview-person-metric ${c[key]?'has-count':''} ${key}" data-progress-status="${key}" title="${hint}"><span><i></i>${label}</span><strong>${c[key]}<small>人</small></strong><em>${key==='attention'?'跟进处理':'查看人员'}${icon('arrow')}</em></button>`).join('')}</div>
        <div class="overview-card-foot"><span>${icon('info')}${r.quota_mode?'按每日目标核对，待处理作品暂不计有效完成':'未报送仅表示网站今天尚未收到记录'}</span><button class="text-button" data-page="people">管理名册 ↗</button></div>
      </section>
      <section class="overview-card overview-inbox" aria-labelledby="overview-inbox-title">
        <div class="overview-card-head"><h2 id="overview-inbox-title">报送处理</h2><span class="overview-period-tag">全部日期</span></div>
        <div id="report-overview-summary" aria-live="polite"><div class="overview-queue-loading">正在读取报送…</div></div>
        <a class="overview-report-entry" href="/report" target="_blank" rel="noreferrer">${icon('external')}打开员工报送入口<span>↗</span></a>
      </section>
    </div>
    <section class="overview-card overview-works" aria-labelledby="overview-works-title">
      <div class="overview-card-head"><div><h2 id="overview-works-title">作品概况</h2><p>${esc(timeScope)} · ${esc(account)}</p></div><button class="text-button" data-overview-works>查看作品 ↗</button></div>
      ${opsOverviewSummary()}
      <details class="overview-filters" ${active?'open':''}><summary><span>${icon('search')}筛选范围<small>部门、人员、账号与发布时间</small></span><span class="overview-filter-toggle"><b class="overview-filter-closed">展开</b><b class="overview-filter-open">收起</b>${icon('arrow')}</span></summary><div class="overview-filter-content">${opsScopeFilter()}<p>部门、小组、员工同时筛选上方人员与报送；发布时间和抖音账号仅筛选作品概况。</p></div></details>
    </section>
  </div>`;
}
function reportOverviewQueue(counts){
  return `<div class="overview-queue-list">${[['review','待核实','核对作品归属'],['failed','处理失败','检查并重新识别'],['rejected','未通过','查看退回原因']].map(([status,label,hint])=>`<button type="button" data-report-open-state="${status}" class="${counts[status]?'has-count':''}"><span>${label}<small>${hint}</small></span><b>${counts[status]||0}</b><span class="overview-row-arrow">›</span></button>`).join('')}</div><div class="overview-queue-waiting"><span class="overview-dot"></span>等待识别 <b>${(counts.queued||0)+(counts.processing||0)}</b> 项</div>`;
}
function opsInteractionSummary(){const s=ops.data.summary;return `<section class="panel"><div class="panel-header"><span class="panel-title">${icon('layers')}作品互动数据</span><small class="subtle">当前筛选 ${s.works} 件作品</small></div><div class="panel-body ops-interaction-body"><div class="stat-grid ops-stats ops-interaction-stats">${Object.entries(metricNames).map(([key,label])=>{const m=s.metrics[key];return opsStat(label+'总数',opsNumber(m.value),`可用 ${m.known} / ${s.works} 件 · 历史值 ${m.stale} 件`)}).join('')}</div><p class="subtle ops-footnote">只汇总已入库的可用指标，暂无数据不计为 0；历史成功值继续保留。查看单条作品或导出，请到作品管理。</p></div></section>`}
function opsCheckFilter(){const p=ops.data.people;return `<section class="panel"><form id="ops-filter" class="panel-body ops-filters ops-check-filter">${reportDeptField()}<div class="field"><label for="check-employee">员工</label><select name="employee" id="check-employee">${opsOpts(p.users.filter(u=>u.role==='employee'),'id','name',ops.filters.employee)}</select></div><div class="field"><label for="check-group">小组</label><select name="group" id="check-group">${opsOpts(p.groups,'id','name',ops.filters.group)}</select></div><div class="field"><label for="check-binding">抖音账号</label><select name="binding" id="check-binding">${opsOpts(ops.data.bindings,'id','nickname',ops.filters.binding)}</select></div><div class="ops-filter-actions"><button type="submit" class="primary">筛选账号</button><button type="button" id="ops-filter-reset" class="secondary">重置</button></div></form></section>`}
function reportGroups(){return (ops.data.people?.groups||[]).map(g=>({...g,name:((ops.data.people.departments||[]).find(d=>d.id===g.department_id)?.name||'未设置部门')+' / '+g.name}))}
opsEditor=function(type,id){reportingBaseEditor(type,id);if(type==='binding'){const field=document.querySelector('#edit-owner_id'),binding=ops.data.bindings.find(b=>b.id===id);if(field)field.innerHTML=opsOpts(ops.data.people.users.filter(u=>u.role==='employee'&&u.enabled),'id','name',binding?.owner_id,'请选择责任员工')}};
opsPeople=function(){
  const p=ops.data.people,allEmployees=p.users.filter(u=>u.role!=='admin'),employees=allEmployees.filter(u=>!u.deleted_at);
  const rows=allEmployees.filter(u=>(reportAdmin.peopleStatus==='deleted'?Boolean(u.deleted_at):!u.deleted_at&&(reportAdmin.peopleStatus==='all'||Boolean(u.enabled)===(reportAdmin.peopleStatus==='enabled')))&&(!reportAdmin.peopleSearch||(u.name+' '+(u.employee_code||'')+' '+reportPersonGroup(u)).toLocaleLowerCase().includes(reportAdmin.peopleSearch.toLocaleLowerCase())));
  return `<div class="workspace-people-grid"><section class="panel"><div class="panel-header report-admin-header"><span class="panel-title">${icon('users')}员工名册 <small class="subtle">${employees.length} 人 · 无需员工密码</small></span><div class="report-admin-actions"><button class="secondary" data-report-person-new>添加人员</button><button class="text-button" data-report-import>批量导入名册</button></div></div><div class="panel-body report-roster-filter"><input type="search" class="filter-input" id="report-roster-search" value="${esc(reportAdmin.peopleSearch)}" aria-label="搜索员工姓名、工号、部门或小组" placeholder="姓名、工号、部门或小组"><select id="report-roster-status" aria-label="员工状态"><option value="all" ${reportAdmin.peopleStatus==='all'?'selected':''}>全部状态</option><option value="enabled" ${reportAdmin.peopleStatus==='enabled'?'selected':''}>在职 / 启用</option><option value="disabled" ${reportAdmin.peopleStatus==='disabled'?'selected':''}>已停用</option></select></div><div class="ops-table-wrap"><table class="ops-table"><thead><tr><th>姓名 / 工号</th><th>部门 / 小组</th><th>状态</th><th>操作</th></tr></thead><tbody>${rows.map(u=>`<tr><td><b>${esc(u.name)}</b><small>${esc(u.employee_code||'未设置工号')}</small></td><td>${esc(reportPersonGroup(u))}</td><td><span class="status-chip ${u.enabled?'ok':''}">${u.deleted_at?'已删除':u.enabled?'在职 / 启用':'已停用'}</span></td><td>${u.deleted_at?`<button class="text-button" data-report-restore="${esc(u.id)}">恢复员工</button>`:`<button class="text-button" data-report-person="${esc(u.id)}">编辑</button>`}<button class="text-button" data-daily-employee="${esc(u.id)}">每日要求</button><button class="text-button" data-user-works="${esc(u.id)}">作品记录</button></td></tr>`).join('')||'<tr><td colspan="4"><div class="empty-state">暂无匹配人员。可添加或批量导入名册；员工首次报送也会自动建档。</div></td></tr>'}</tbody></table></div></section><section class="panel"><div class="panel-header report-admin-header"><span class="panel-title">${icon('layers')}部门与小组</span><div class="report-admin-actions"><button class="secondary" data-report-dept-new>创建部门</button><button class="secondary" data-report-group-new>创建小组</button></div></div><div class="panel-body">${(p.departments||[]).map(d=>`<div class="report-department"><div class="ops-check-row"><div><b>${esc(d.name)}</b><small>${p.groups.filter(g=>g.department_id===d.id).length} 个小组 · ${employees.filter(u=>p.groups.some(g=>g.department_id===d.id&&g.id===u.group_id)).length} 人</small></div><button class="text-button" data-report-dept="${esc(d.id)}">编辑部门</button></div>${p.groups.filter(g=>g.department_id===d.id).map(g=>reportGroupRow(g,employees)).join('')}</div>`).join('')||'<div class="empty-state">部门与小组将随员工报送自动生成；管理员可以调整名称、归属与负责人。</div>'}${p.groups.filter(g=>!(p.departments||[]).some(d=>d.id===g.department_id)).map(g=>reportGroupRow(g,employees)).join('')}</div></section></div>`;
};
function reportPersonGroup(u){const p=ops.data.people,g=p.groups.find(g=>g.id===u.group_id),d=(p.departments||[]).find(d=>d.id===g?.department_id);return [d?.name,g?.name].filter(Boolean).join(' / ')||'未分组'}
function reportGroupRow(g,employees){return `<div class="ops-check-row report-group-row"><div><b>${esc(g.name)}</b><small>${employees.filter(u=>u.group_id===g.id).length} 人 · 负责人：${esc(ops.data.people.users.find(u=>u.id===g.leader_id)?.name||'未指定')}</small></div><button class="text-button" data-report-group="${esc(g.id)}">编辑小组</button></div>`}
opsSetup=function(){if(ops.data.people.users.some(u=>u.role==='employee'))return '';return `<section class="panel"><div class="panel-header"><span class="panel-title">${icon('check')}建立部门作品台账</span></div><div class="panel-body ops-start-steps"><a class="secondary" href="/report" target="_blank" rel="noreferrer">1. 员工填写姓名、部门和小组 ↗</a><a class="secondary" href="/report" target="_blank" rel="noreferrer">2. 粘贴链接并扫码核验 ↗</a><button class="secondary" data-page="audit">3. 处理账号不一致等异常</button><p class="subtle">无需为员工创建网站账号。人员自动建档，登录账号与作品作者一致就自动归档，老板集中处理异常。</p></div></section>`};
function reportInspectionLabel(binding){
  return {complete:'本次检查结束',incomplete:'需要核实',error:'检查失败',unknown:'尚未检查'}[binding.check_state]||'需要核实';
}
function reportInspectionResult(message,binding=null){
  if(!binding)return `<p class="report-inspection-detail">${esc(message||'尚未执行巡检。')}</p>`;
  const stats=binding.publication_stats;
  const published=stats?.latest_published?esc(opsDate(stats.latest_published)):'暂无数据';
  const reported=stats?.latest_work_reported_at?esc(opsDate(stats.latest_work_reported_at)):stats?.latest_work_id?'暂无报送记录':'暂无数据';
  return `<div class="report-inspection-result"><div class="report-publication-summary"><span>作者最新作品发布时间<strong>${published}</strong><small class="report-publication-unconfirmed">平台最新待核实</small></span><span>最新作品报送到网页时间<strong>${reported}</strong></span><span>监测期间发布作品<strong>${stats?`已发现 ${esc(stats.monitor_count)} 件`:'待统计'}</strong></span></div><p class="report-publication-range">统计期间：${esc(opsDate(stats?.period_start||binding.monitor_start))} — ${stats?esc(opsDate(stats.as_of)):'当前'}（北京时间）</p><p class="report-publication-note">发布时间取自抖音；报送时间对应同一作品首次提交到本网站的时间。采集可能不完整，当前展示已获取记录。</p></div>`;
}
opsBindings=function(){
  const bindings=ops.data.bindings,owners=new Map(),people=ops.data.people?.users||[];
  for(const account of bindings){
    const ownerId=account.owner_id||'';
    if(!owners.has(ownerId)){
      const person=people.find(u=>u.id===ownerId);
      owners.set(ownerId,{id:ownerId,name:person?.name||account.employee_name||'未分配负责人',code:person?.employee_code||'',accounts:[]});
    }
    owners.get(ownerId).accounts.push(account);
  }
  const groups=[...owners.values()].sort((a,b)=>Boolean(b.id)-Boolean(a.id)||a.name.localeCompare(b.name,'zh-CN')||a.id.localeCompare(b.id));
  return `<section class="panel"><div class="panel-header report-admin-header"><span class="panel-title">${icon('link')}抖音账号与责任人 <small class="subtle">${bindings.length} 个账号 · ${groups.filter(g=>g.id).length} 位负责人</small></span><button class="primary" id="ops-new-binding">手动绑定账号</button></div><div class="workspace-intro">按负责人集中展示，每组显示账号总数，包含已停用账号。</div><div class="ops-table-wrap"><table class="ops-table workspace-binding-table"><thead><tr><th>抖音账号</th><th>所属小组</th><th>使用状态</th><th>操作</th></tr></thead>${groups.map(g=>{
    const enabled=g.accounts.filter(b=>b.enabled).length;
    return `<tbody class="workspace-owner-group" data-binding-owner="${esc(g.id)}"><tr class="workspace-owner-heading"><th colspan="4" scope="rowgroup"><div class="workspace-owner-summary"><span><b>${esc(g.name)}</b><span class="workspace-owner-count">${g.accounts.length} 个账号</span>${g.code?`<small>工号 ${esc(g.code)}</small>`:''}</span><small>启用 ${enabled} · 停用 ${g.accounts.length-enabled}</small></div></th></tr>${g.accounts.map(b=>`<tr><td><b>${esc(b.nickname||'待识别昵称')}</b><small>UID：${esc(b.uid||'待识别')}</small></td><td>${esc(b.group_name||'未分组')}</td><td><span class="status-chip ${b.enabled?'ok':''}">${b.enabled?'已启用':'已停用'}</span></td><td><div class="workspace-row-actions"><a class="link-inline" href="${safeOpsUrl(b.homepage)}" target="_blank" rel="noreferrer">主页 ↗</a><button class="text-button" data-edit-binding="${esc(b.id)}">编辑 / 启停</button><button class="text-button danger-text" data-report-binding-delete="${esc(b.id)}">删除</button></div></td></tr>`).join('')}</tbody>`;
  }).join('')||'<tbody><tr><td colspan="4"><div class="empty-state">核验报送成功后自动绑定账号，也可手动添加。</div></td></tr></tbody>'}</table></div></section>`;
};
function reportDeleteBinding(id){
  const binding=ops.data.bindings.find(b=>b.id===id);if(!binding)return;
  opsModal('删除抖音账号绑定',`<form id="report-delete-binding-form"><p class="detail-list">确定删除这个抖音账号绑定？</p><p class="report-delete-work-title">${esc(binding.nickname)}</p><p class="subtle ops-footnote">责任人：${esc(binding.employee_name)} · ${esc(binding.group_name||'未分组')}<br>UID：${esc(binding.uid||'待采集')}<br>将删除本系统的账号绑定、采集登录信息和关联作品/报送数据，只留日志，不可页面恢复。之后可以重新添加或通过核验报送建立绑定；不会产生停用限制。平台账号与视频不受影响。</p><p class="ops-form-error" id="report-delete-binding-error" role="alert"></p><div class="report-employee-editor-actions"><button class="secondary" type="button" id="report-delete-binding-cancel">取消</button><button class="secondary danger-text" type="submit">确认删除账号</button></div></form>`);
  document.querySelector('#report-delete-binding-cancel').onclick=()=>document.querySelector('#detail-dialog').close();
  document.querySelector('#report-delete-binding-form').onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector('[type=submit]');button.disabled=true;try{const result=await post('/ops/bindings/delete',{id,confirmed:true,permanent:true});document.querySelector('#detail-dialog').close();toast(result.message);await loadOps()}catch(error){document.querySelector('#report-delete-binding-error').textContent=error.message}finally{button.disabled=false}};
}
opsSettings=function(){
  if(['targets','tasks'].includes(ops.settingsTab))ops.settingsTab='rules';
  const tab=ops.settingsTab;
  const tabs=[['rules','报送规则'],['connection','采集连接'],['logs','操作日志'],['access','访问与备份']];
  const bar=`<div class="ops-tabs" role="tablist">${tabs.map(([id,name])=>`<button type="button" role="tab" aria-selected="${id===tab}" data-ops-settings-tab="${id}">${name}</button>`).join('')}</div>`;
  if(tab==='access')return bar+'<div id="report-access-panel"><section class="panel"><div class="panel-body report-loading">正在读取访问地址和备份…</div></section></div>';
  if(tab==='rules')return bar+reportSubmissionRules();
  const html=reportingBaseSettings();return bar+html.slice(html.indexOf('</div>')+6);
};

function reportDeleteWork(id){const work=ops.data.works?.items.find(w=>w.id===id);if(!work)return;opsModal('删除作品记录',`<form id="report-delete-work-form"><p class="detail-list">确定删除这条作品记录？</p><p class="report-delete-work-title">${esc(work.description||work.id)}</p><p class="subtle ops-footnote">作者：${esc(work.nickname)}<br>作品 ID：${esc(id)}<br>将从数据库删除作品详情、首次报送、统计、备注及同一作品的所有报送记录，只保留操作日志。不可从页面恢复；再次提交按新报送处理。抖音平台的视频保留，后续巡检可能重新发现。</p><p class="ops-form-error" id="report-delete-work-error" role="alert"></p><div class="report-employee-editor-actions"><button class="secondary" type="button" id="report-delete-work-cancel">取消</button><button class="secondary danger-text" type="submit">确认删除</button></div></form>`);document.querySelector('#report-delete-work-cancel').onclick=()=>document.querySelector('#detail-dialog').close();document.querySelector('#report-delete-work-form').onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector('[type=submit]');button.disabled=true;try{const result=await post('/ops/works/delete',{id,confirmed:true,permanent:true});document.querySelector('#detail-dialog').close();toast(result.message);await loadOps()}catch(error){document.querySelector('#report-delete-work-error').textContent=error.message}finally{button.disabled=false}};}
function reportQueueFrame(){return `<section class="panel" id="report-review-panel"><div class="panel-header report-admin-header"><span class="panel-title">${icon('tasks')}员工报送处理</span><button class="text-button" data-report-reload>刷新报送</button></div><div class="panel-body report-review-controls"><form id="report-queue-filter" class="report-queue-filter"><div class="field"><label for="report-queue-date">报送日期</label><input type="date" id="report-queue-date" name="date" value="${esc(reportAdmin.filters.date||'')}"></div><div class="field"><label for="report-queue-department">部门</label><select name="department" id="report-queue-department">${opsOpts(ops.data.people.departments||[],'id','name',reportAdmin.filters.department)}</select></div><div class="field"><label for="report-queue-group">小组</label><select name="group" id="report-queue-group">${opsOpts(ops.data.people.groups,'id','name',reportAdmin.filters.group)}</select></div><div class="field"><label for="report-queue-employee">员工</label><select name="employee" id="report-queue-employee">${opsOpts(ops.data.people.users.filter(u=>u.role==='employee'),'id','name',reportAdmin.filters.employee)}</select></div><div class="field"><label for="report-queue-state">处理状态</label><select id="report-queue-state" name="state">${opsOpts(Object.entries(reportStateNames).map(([id,name])=>({id,name})),'id','name',reportAdmin.filters.state)}</select></div><div class="field"><label for="report-queue-search">姓名、工号、作品或账号</label><input id="report-queue-search" name="search" value="${esc(reportAdmin.filters.search||'')}" placeholder="输入关键词"></div><div class="ops-filter-actions"><button class="primary" type="submit">筛选</button><button class="secondary" type="button" data-report-reset-filters>重置</button></div></form><div class="report-batch-bar"><label><input type="checkbox" id="report-select-all"> 全选本页</label><span id="report-selected-count">已选 0 项</span><button class="secondary" data-report-batch="approve">批量审核通过</button><button class="secondary" data-report-batch="retry">重试识别</button><button class="text-button danger-text" data-report-batch="reject">审核不通过</button><button class="secondary danger-text" data-report-delete-selected>删除所选</button></div><p class="subtle ops-footnote">全选仅当前页。删除会清除同一作品及关联报送，只保留日志，不可从页面恢复；操作前需确认。</p></div><div id="report-queue-content" aria-live="polite"><div class="report-loading">正在读取报送…</div></div></section>`}
function reportIsReviewable(item){return !item.deleted_at&&['review','failed'].includes(item.status)}
function reportIsSelectable(item){return item.deleted_at||item.status!=='processing'}
async function reportLoadQueue(){const seq=++reportAdmin.load,page=state.page,{state:workState,deleted:workDeleted,...scope}=ops.filters;try{const result=await api('/ops/reporting?'+new URLSearchParams({...(page==='overview'?{department:scope.department||'',employee:scope.employee||'',group:scope.group||''}:{employee:scope.employee||'',group:scope.group||'',department:scope.department||'',...reportAdmin.filters}),status:page==='overview'?'':reportAdmin.filters.state||'',page:page==='overview'?1:reportAdmin.page}));if(seq!==reportAdmin.load||state.page!==page)return;reportAdmin.result=result;reportAdmin.page=result.page;reportAdmin.selected.clear();
  if(page==='overview'){const target=document.querySelector('#report-overview-summary');if(target)target.innerHTML=reportOverviewQueue(result.counts||{});return}
  const target=document.querySelector('#report-queue-content');if(!target)return;
  target.innerHTML=`<div class="ops-table-wrap report-review-scroll" tabindex="0" role="region" aria-label="报送记录，可滚动查看"><table class="ops-table report-review-table report-review-compact"><colgroup><col style="width:50px"><col><col style="width:172px"><col style="width:150px"><col style="width:128px"><col style="width:144px"></colgroup><thead><tr><th>选择</th><th>作品 / 作者</th><th>发布 / 报送时间</th><th>报送人 / 归属</th><th>处理状态</th><th>操作</th></tr></thead><tbody>${result.items.map(item=>`<tr><td>${reportIsSelectable(item)?`<input type="checkbox" data-report-select="${esc(item.id)}" aria-label="选择报送 ${esc(item.description||item.work_id||item.id)}">`:'—'}</td><td><button type="button" class="report-compact-title" data-report-detail="${esc(item.id)}" title="${esc(item.description||item.work_id||'等待识别作品')}">${esc(item.description||item.work_id||'等待识别作品')}</button><small class="report-compact-author">${esc(item.nickname||'作者待识别')}${safeOpsUrl(item.link)?` · <a class="link-inline" href="${safeOpsUrl(item.link)}" target="_blank" rel="noreferrer">原作品 ↗</a>`:''}</small></td><td><div class="report-compact-times"><small><span>发布</span><time>${opsDate(item.published)}</time></small><small><span>报送</span><time>${opsDate(item.received_at)}</time></small></div></td><td><b>${esc(item.employee_name||item.reporter_name||'未知报送人')}</b><small class="report-compact-org" title="${esc([item.department_name,item.group_name].filter(Boolean).join(' / '))}">${esc([item.department_name,item.group_name].filter(Boolean).join(' / '))}</small>${item.owner_name&&item.owner_name!==item.employee_name?`<small>责任人：${esc(item.owner_name)}</small>`:''}</td><td><span class="status-chip ${['submitted','duplicate'].includes(item.status)?'ok':''}">${reportStateNames[item.status]||esc(item.status)}</span><small>${{match:'作者匹配',mismatch:'作者未匹配',unverified:'账号未核验'}[item.account_match]||'账号未核验'}</small>${item.reporter_note?`<button type="button" class="text-button report-note-flag" data-report-detail="${esc(item.id)}">有员工备注</button>`:''}</td><td><div class="report-compact-actions"><button type="button" class="text-button" data-report-detail="${esc(item.id)}">详情</button>${reportQueueActions(item)}</div></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty-state">当前没有匹配的报送记录。</div></td></tr>'}</tbody></table></div><div class="log-pagination ops-pages"><button class="secondary" data-report-page="-1" ${result.page<=1?'disabled':''}>上一页</button><span class="subtle">共 ${result.total} 项 · 每页 ${result.page_size||30} 项 · 第 ${result.page} / ${Math.max(1,Math.ceil(result.total/(result.page_size||30)))} 页</span><button class="secondary" data-report-page="1" ${result.page*(result.page_size||30)>=result.total?'disabled':''}>下一页</button></div>`;reportUpdateSelected();
}catch(error){const target=document.querySelector(page==='overview'?'#report-overview-summary':'#report-queue-content');if(target)target.innerHTML=`<p class="report-admin-error">${esc(error.message)}</p>`;else toast(error.message)}}
function reportItemDetail(id){
  const item=reportAdmin.result?.items.find(i=>i.id===id);if(!item)return;
  const accounts=item.login_accounts?.length?item.login_accounts:item.login_account?.sec_uid?[item.login_account]:[];
  opsModal('报送详情',`<div class="report-detail-content"><p class="report-detail-description">${esc(item.description||item.work_id||'等待识别作品')}</p><dl class="report-detail-facts"><dt>作品作者</dt><dd>${esc(item.nickname||'待识别')}</dd><dt>发布时间</dt><dd>${opsDate(item.published)}</dd><dt>报送时间</dt><dd>${opsDate(item.received_at)}</dd><dt>报送人</dt><dd>${esc(item.employee_name||item.reporter_name||'未知')} · ${esc([item.department_name,item.group_name].filter(Boolean).join(' / '))}</dd><dt>账号责任人</dt><dd>${esc(item.owner_name||'尚未确认')}</dd><dt>处理状态</dt><dd>${esc(reportStateNames[item.status]||item.status)}</dd><dt>作者核验</dt><dd>${{match:'作品作者匹配已核验账号',mismatch:'作品作者未匹配任何核验账号',unverified:'未完成抖音账号核验'}[item.account_match]||'未核验'}</dd><dt>核验账号</dt><dd>${accounts.map(a=>`${esc(a.nickname||a.sec_uid)}${safeOpsUrl(a.homepage)?` <a class="link-inline" href="${safeOpsUrl(a.homepage)}" target="_blank" rel="noreferrer">主页 ↗</a>`:''}`).join('<br>')||'无'}</dd></dl><section class="report-detail-note"><b>员工备注</b><p>${esc(item.reporter_note||'未填写备注')}</p></section><section class="report-detail-note"><b>处理说明</b><p>${esc(item.message||'暂无说明')}</p>${item.review_note?`<p>审核说明：${esc(item.review_note)}</p>`:''}</section><details class="workspace-details"><summary>作品与作者标识</summary><p>作品 ID：${esc(item.work_id||'待识别')}<br>作者标识：${esc(item.sec_uid||'待识别')}</p></details>${safeOpsUrl(item.link)?`<a class="link-inline" href="${safeOpsUrl(item.link)}" target="_blank" rel="noreferrer">打开报送作品 ↗</a>`:''}</div>`);
}
function reportQueueActions(item){
  const id=esc(item.id);
  if(item.deleted_at)return `<button class="text-button danger-text" data-report-item-delete="${id}">清除历史残留</button>`;
  return `${item.status==='review'?`<button class="text-button" data-report-review="${id}">审核通过</button>`:''}${item.status==='failed'?`<button class="text-button" data-report-retry="${id}">重试识别</button>`:''}${reportIsReviewable(item)?`<button class="text-button danger-text" data-report-reject="${id}">审核不通过</button>`:''}${item.status!=='processing'?`<button class="text-button danger-text" data-report-item-delete="${id}">删除</button>`:'<small>识别完成后可删除</small>'}`;
}
function reportUpdateSelected(){
  const count=document.querySelector('#report-selected-count');if(count)count.textContent=`已选 ${reportAdmin.selected.size} 项`;
  const items=(reportAdmin.result?.items||[]).filter(i=>reportAdmin.selected.has(i.id));
  document.querySelectorAll('[data-report-batch]').forEach(button=>{button.disabled=!items.length||items.some(i=>!reportIsReviewable(i))});
  const remove=document.querySelector('[data-report-delete-selected]');
  if(remove)remove.disabled=!items.length;
  const all=document.querySelector('#report-select-all');if(all){const inputs=[...document.querySelectorAll('[data-report-select]')];all.disabled=!inputs.length;all.checked=!!inputs.length&&inputs.every(el=>el.checked);all.indeterminate=inputs.some(el=>el.checked)&&!all.checked}
}
function reportDeleteReports(ids){
  const items=(reportAdmin.result?.items||[]).filter(i=>ids.includes(i.id)&&reportIsSelectable(i));
  if(!items.length)return toast('请先选择要删除的报送记录。');
  opsModal('删除报送记录',`<form id="report-delete-items-form"><p class="detail-list">确定删除选中的 ${items.length} 条报送记录？</p><ul class="report-delete-items-list">${items.map(i=>`<li>${esc(i.employee_name||i.reporter_name||'未知报送人')} · ${esc(i.description||i.work_id||i.link)}</li>`).join('')}</ul><p class="subtle ops-footnote">将从数据库删除选中报送涉及的作品详情、首次报送、统计、备注和同一作品的所有报送记录（可能包括其他员工或其他页的记录），只保留操作日志。不可从页面恢复；再次提交按新报送处理。抖音平台视频保留；再次报送会重新识别。</p><p class="ops-form-error" id="report-delete-items-error" role="alert"></p><div class="report-employee-editor-actions"><button type="button" class="secondary" id="report-delete-items-cancel">取消</button><button type="submit" class="secondary danger-text">确认删除 ${items.length} 条</button></div></form>`);
  document.querySelector('#report-delete-items-cancel').onclick=()=>document.querySelector('#detail-dialog').close();
  document.querySelector('#report-delete-items-form').onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector('[type=submit]');button.disabled=true;try{const result=await post('/ops/reporting/delete',{ids:items.map(i=>i.id),confirmed:true,permanent:true});document.querySelector('#detail-dialog').close();toast(result.message);await loadOps()}catch(error){document.querySelector('#report-delete-items-error').textContent=error.message}finally{button.disabled=false}};
}
loadOps=async function(){if(['checks','missing'].includes(state.page)){state.page='unreported';history.replaceState(null,'','#unreported')}const page=state.page,expected=ops.sequence+1;await reportingBaseLoad();if(expected!==ops.sequence||page!==state.page||ops.user?.role!=='admin'||!document.querySelector('#ops-body'))return;
  opsBindSearchFilters();
  if(page==='people')reportBindRoster();
  if(page==='audit'){document.querySelector('#ops-body')?.insertAdjacentHTML('afterbegin',reportQueueFrame());document.querySelector('#report-queue-filter').onsubmit=event=>{event.preventDefault();reportAdmin.filters=Object.fromEntries(new FormData(event.target));reportAdmin.page=1;reportLoadQueue()};document.querySelector('#report-select-all').onchange=event=>{document.querySelectorAll('[data-report-select]').forEach(el=>{el.checked=event.target.checked;if(el.checked)reportAdmin.selected.add(el.dataset.reportSelect);else reportAdmin.selected.delete(el.dataset.reportSelect)});reportUpdateSelected()};opsBindSearchFilters();await reportLoadQueue()}
  if(page==='overview')await reportLoadQueue();
  if(page==='opssettings'&&ops.settingsTab==='access')await reportLoadAccess();
  if(page==='opssettings'&&ops.settingsTab==='rules')await reportLoadDailyRules();
  
  if(page==='opssettings'&&ops.settingsTab==='connection'){const note=document.querySelector('#ops-connection-form .ops-footnote');if(note)note.textContent='作品报送不要求员工登录网站或逐次登录抖音。后台统一使用已保存的有效采集登录信息；平台要求登录时仍需管理员维护可用 Cookie。仅使用原项目的分享解析与作品详情能力，不再自动查询账号发布列表。'}
};
function reportBindRoster(){document.querySelector('#report-roster-search')?.addEventListener('input',event=>{reportAdmin.peopleSearch=event.target.value;const search=event.target,position=search.selectionStart;document.querySelector('#ops-body').innerHTML=opsPeople();hydrate();reportBindRoster();const next=document.querySelector('#report-roster-search');next.focus();next.setSelectionRange(position,position)});document.querySelector('#report-roster-status')?.addEventListener('change',event=>{reportAdmin.peopleStatus=event.target.value;document.querySelector('#ops-body').innerHTML=opsPeople();hydrate();reportBindRoster()})}
function reportEditor(type,id){
  const p=ops.data.people;let record={},body='',title='',endpoint='';
  if(type==='person'){record=p.users.find(u=>u.id===id)||{};title=id?'编辑员工名册':'添加员工';endpoint='employees';body=opsField('姓名','name',record.name||'','text','required maxlength="40"')+opsField('工号（区分同名员工）','employee_code',record.employee_code||'','text','required maxlength="40"')+`<div class="field"><label for="report-edit-group">部门 / 小组</label><select name="group_id" id="report-edit-group" required>${opsOpts(reportGroups(),'id','name',record.group_id,'选择所属小组')}</select></div><label class="ops-checkbox"><input name="enabled" type="checkbox" ${record.enabled!==0?'checked':''}>在职 / 可报送</label><p class="subtle">员工无需用户名和密码。停用人员后保留作品与历史报送记录。</p>`;}
  if(type==='dept'){record=(p.departments||[]).find(d=>d.id===id)||{};title=id?'编辑部门':'创建部门';endpoint='departments';body=opsField('部门名称','name',record.name||'','text','required maxlength="40"');}
  if(type==='group'){record=p.groups.find(g=>g.id===id)||{};title=id?'编辑小组':'创建小组';endpoint='groups';body=opsField('小组名称','name',record.name||'','text','required maxlength="40"')+`<div class="field"><label for="report-edit-department">所属部门</label><select name="department_id" id="report-edit-department" required>${opsOpts(p.departments||[],'id','name',record.department_id,'选择部门')}</select></div><div class="field"><label for="report-edit-leader">小组负责人</label><select name="leader_id" id="report-edit-leader">${opsOpts(p.users.filter(u=>u.enabled),'id','name',record.leader_id,'暂不指定')}</select></div>`;}
  opsModal(title,`<form id="report-editor">${body}<p class="ops-form-error" id="report-editor-error" role="alert"></p><div class="report-employee-editor-actions"><button class="primary" type="submit">保存</button>${type==='person'&&id?'<button class="text-button danger-text" id="report-delete-employee" type="button">删除员工</button>':''}</div>${type==='person'&&id?`<div id="report-delete-confirm" class="report-delete-confirm" hidden><b>确定删除 ${esc(record.name)}？</b><p>将删除员工、名下账号绑定及关联作品和报送数据，只留操作日志，不可页面恢复。删除不设置停用限制；之后报送可重新建档。仅需暂时禁止使用时请取消“在职 / 可报送”，不要删除。</p><button type="button" class="secondary" id="report-delete-cancel">暂不删除</button><button type="button" class="secondary danger-text" id="report-delete-confirm-button">确认删除员工</button></div>`:''}</form>`);
  if(type==='person'&&id){const panel=document.querySelector('#report-delete-confirm');document.querySelector('#report-delete-employee').onclick=()=>{panel.hidden=false};document.querySelector('#report-delete-cancel').onclick=()=>{panel.hidden=true};document.querySelector('#report-delete-confirm-button').onclick=async event=>{const buttons=[...document.querySelectorAll('#report-editor button')];buttons.forEach(b=>b.disabled=true);try{const result=await post('/ops/employees/delete',{id,confirmed:true,permanent:true});document.querySelector('#detail-dialog').close();toast(result.message);await loadOps()}catch(error){document.querySelector('#report-editor-error').textContent=error.message}finally{buttons.forEach(b=>b.disabled=false)}};}
  document.querySelector('#report-editor').onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector('[type=submit]');button.disabled=true;try{const data=Object.fromEntries(new FormData(event.target));if(id)data.id=id;if(type==='person')data.enabled=event.target.elements.enabled.checked;await post('/ops/'+endpoint,data);document.querySelector('#detail-dialog').close();toast('已保存');await loadOps()}catch(error){document.querySelector('#report-editor-error').textContent=error.message}finally{button.disabled=false}};
}
function reportParseCSV(text){const delimiter=text.split(/\r?\n/)[0].includes('\t')?'\t':',';let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++}else quoted=!quoted}else if(ch===delimiter&&!quoted){row.push(cell.trim());cell=''}else if((ch==='\n'||ch==='\r')&&!quoted){if(ch==='\r'&&text[i+1]==='\n')i++;row.push(cell.trim());if(row.some(Boolean))rows.push(row);row=[];cell=''}else cell+=ch}if(quoted)throw Error('CSV 引号未闭合，请检查文件。');row.push(cell.trim());if(row.some(Boolean))rows.push(row);if(!rows.length)throw Error('请先粘贴或选择员工名单。');const header=rows.shift().map(x=>x.replace(/^\uFEFF/,'').trim());const aliases={name:['姓名','员工姓名','name'],employee_code:['工号','员工工号','employee_code'],department:['部门','department'],group:['小组','组别','group']};const indexes=Object.fromEntries(Object.entries(aliases).map(([key,names])=>[key,header.findIndex(x=>names.includes(x))]));if(Object.values(indexes).some(i=>i<0))throw Error('表头需要包含：姓名、工号、部门、小组。');return rows.map(row=>Object.fromEntries(Object.entries(indexes).map(([key,index])=>[key,row[index]||''])))}
function reportDownloadTemplate(){const blob=new Blob(['\uFEFF姓名,工号,部门,小组\r\n张三,E001,运营部,一组\r\n李四,E002,运营部,二组\r\n'],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='员工名册导入模板.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function reportImport(){opsModal('批量导入员工名册',`<form id="report-import-form"><p class="subtle ops-footnote">按工号识别员工，可创建或更新名册，同时创建缺少的部门和小组。先预览再导入，员工无需设置密码。</p><div class="report-admin-actions"><button class="secondary" type="button" id="report-import-template">下载 CSV 模板</button><label class="secondary report-file-button">选择 CSV 文件<input type="file" id="report-import-file" accept=".csv,.tsv,text/csv,text/tab-separated-values" hidden></label></div><div class="field section-spacer"><label for="report-import-text">员工名单（支持从 Excel 复制含表头的四列）</label><textarea id="report-import-text" rows="7" placeholder="姓名,工号,部门,小组&#10;张三,E001,运营部,一组" required></textarea></div><div id="report-import-preview"></div><p class="ops-form-error" id="report-import-error" role="alert"></p><div class="result-actions"><button type="button" class="secondary" id="report-import-validate">预览名单</button><button class="primary" type="submit" id="report-import-save" disabled>导入名册</button></div></form>`);let parsed=null;document.querySelector('#report-import-template').onclick=reportDownloadTemplate;document.querySelector('#report-import-file').onchange=async event=>{const file=event.target.files[0];if(!file)return;if(file.size>1024*1024){document.querySelector('#report-import-error').textContent='文件需小于 1 MB。';return}document.querySelector('#report-import-text').value=await file.text();parsed=null;document.querySelector('#report-import-save').disabled=true};document.querySelector('#report-import-text').oninput=()=>{parsed=null;document.querySelector('#report-import-save').disabled=true};document.querySelector('#report-import-validate').onclick=()=>{try{parsed=reportParseCSV(document.querySelector('#report-import-text').value);if(!parsed.length||parsed.length>1000)throw Error('一次导入 1–1000 人。');document.querySelector('#report-import-preview').innerHTML=`<p class="subtle">共 ${parsed.length} 人，预览前 5 人：</p><div class="ops-table-wrap"><table class="ops-table"><thead><tr><th>姓名</th><th>工号</th><th>部门</th><th>小组</th></tr></thead><tbody>${parsed.slice(0,5).map(row=>'<tr>'+['name','employee_code','department','group'].map(k=>`<td>${esc(row[k])}</td>`).join('')+'</tr>').join('')}</tbody></table></div>`;document.querySelector('#report-import-error').textContent='';document.querySelector('#report-import-save').disabled=false}catch(error){parsed=null;document.querySelector('#report-import-save').disabled=true;document.querySelector('#report-import-error').textContent=error.message}};document.querySelector('#report-import-form').onsubmit=async event=>{event.preventDefault();if(!parsed)return;const button=document.querySelector('#report-import-save');button.disabled=true;try{const result=await post('/ops/employees/import',{rows:parsed});document.querySelector('#detail-dialog').close();toast(result.message||`已导入 ${parsed.length} 人`);loadOps()}catch(error){document.querySelector('#report-import-error').textContent=error.message;button.disabled=false}}}
function reportReview(ids,action){
  const items=(reportAdmin.result?.items||[]).filter(i=>ids.includes(i.id));if(!items.length||items.some(i=>!reportIsReviewable(i)))return toast('仅待核实或失败的报送可以核实、重试或审核不通过。');
  if(action==='retry')return reportDoReview({ids,action});if(action==='approve'&&items.some(item=>item.status!=='review'))return toast('请先重试识别，成功读取作品后才能审核通过。');
  const approving=action==='approve',first=items[0],sameOwner=items.every(i=>i.owner_id&&i.owner_id===first.owner_id),sameClaim=items.every(i=>i.employee_id===first.employee_id),defaultOwner=sameOwner?first.owner_id:sameClaim?first.employee_id:'';
  opsModal(approving?'审核通过：确认作品责任人':'审核不通过：填写原因',`<form id="report-review-form"><p class="subtle ops-footnote">本次处理 ${items.length} 项报送。${approving?'通过后，作品将记入所选责任人的作品台账，员工回执显示“已报送”。报送时间沿用系统首次接收时间，不改成现在，也不会把逾期变成按时。请先核对作品作者、核验账号和员工备注；新账号会关联所选责任人，已有归属不能在这里改写。':'本次报送将标记为“未通过核实”，不会登记为有效报送。原报送和处理原因继续保留，员工可在回执中查看；这不是删除操作。'}</p>${approving&&items.every(i=>!i.employee_id)&&sameClaim?`<label class="ops-checkbox"><input id="report-create-person" type="checkbox">为此报送人创建名册（无需网站账号密码）</label><div id="report-new-person" hidden>${opsField('姓名','claim_name',first.reporter_name||'','text','maxlength="40"')}${opsField('工号（留空自动生成）','claim_code',first.employee_code||'','text','maxlength="40"')}${opsField('部门','claim_department',first.department_name||'','text','maxlength="40"')}${opsField('小组','claim_group',first.group_name||'','text','maxlength="40"')}</div>`:''}${approving?`<div class="field"><label for="report-review-owner">这件作品记在哪位员工名下？</label><select id="report-review-owner" name="owner_id" required>${opsOpts(ops.data.people.users.filter(u=>u.role!=='admin'&&u.enabled),'id','name',defaultOwner,'选择责任人')}</select></div>`:''}<div class="field"><label for="report-review-note">${approving?'审核说明（选填，方便日后查阅）':'不通过原因（员工可见，必填）'}</label><textarea name="note" id="report-review-note" maxlength="1000" ${approving?'':'required minlength="2"'}></textarea></div><p class="ops-form-error" id="report-review-error" role="alert"></p><button class="primary" type="submit">${approving?'确认审核通过':'确认审核不通过'}</button></form>`);const create=document.querySelector('#report-create-person');if(create)create.onchange=()=>{document.querySelector('#report-new-person').hidden=!create.checked;const owner=document.querySelector('#report-review-owner');owner.required=!create.checked;owner.disabled=create.checked;};document.querySelector('#report-review-form').onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;try{const form=Object.fromEntries(new FormData(event.target));await post('/ops/reporting/review',{ids,action,owner_id:form.owner_id,note:form.note,...(create?.checked?{create_reporter:true,new_reporter:{name:form.claim_name,employee_code:form.claim_code,department:form.claim_department,group:form.claim_group}}:{})});document.querySelector('#detail-dialog').close();toast(approving?'审核通过，已登记为有效报送':'已记录审核不通过及原因');await loadOps()}catch(error){document.querySelector('#report-review-error').textContent=error.message}finally{button.disabled=false}};
}
async function reportDoReview(data){try{const result=await post('/ops/reporting/review',data);toast(result.message||'已加入重试队列');await reportLoadQueue()}catch(error){toast(error.message)}}
function reportStoredDate(value){if(value===null||value===undefined||value==='')return '暂无数据';const timestamp=typeof value==='number'||/^\d+(?:\.\d+)?$/.test(String(value))?Number(value):Date.parse(value)/1000;return Number.isFinite(timestamp)?opsDate(timestamp):'暂无数据'}
async function reportLoadAccess(){try{const [network,backups]=await Promise.all([api('/ops/network'),api('/ops/backups')]);const target=document.querySelector('#report-access-panel');if(!target)return;const urls=network.employee_urls||[];target.innerHTML=`<section class="panel"><div class="panel-header"><span class="panel-title">${icon('link')}员工访问地址</span></div><div class="panel-body"><p class="subtle ops-footnote">员工电脑或手机连接可访问服务器的公司局域网后，打开下面地址报送。服务器需保持开机。</p>${urls.length?urls.map(url=>`<div class="report-network-url"><a class="link-inline" href="${esc(url)}" target="_blank" rel="noreferrer">${esc(url)}</a><button class="text-button" data-report-copy="${esc(url)}">复制地址</button></div>`).join(''):'<p class="subtle">暂未检测到可用的局域网地址。请检查服务器网络连接。</p>'}<div class="report-network-url"><span>本机报送：${esc(network.local_employee_url||location.origin+'/report')}</span><a class="link-inline" href="/report" target="_blank" rel="noreferrer">打开 ↗</a></div><p class="subtle">监听地址：${esc(network.listen_host||'127.0.0.1')} · 其他设备使用局域网地址，不能使用它们自己的 127.0.0.1。</p>${network.firewall?.message?`<p class="subtle">${esc(network.firewall.message)}</p>`:''}</div></section><section class="panel"><div class="panel-header report-admin-header"><span class="panel-title">${icon('database')}SQLite 备份</span><button class="secondary" data-report-backup>立即备份</button></div><div class="panel-body"><p class="subtle ops-footnote">自动备份：${esc(backups.automatic==='daily'?'每日':backups.automatic||'每日')} · 保留 ${esc(backups.retention||14)} 份。备份包含业务数据和登录凭据，请由管理员保管。</p>${(backups.items||[]).map(item=>`<div class="ops-check-row"><div><b>${esc(item.name)}</b><small>${reportStoredDate(item.created_at)} · ${opsNumber(Math.round((item.size||0)/1024))} KB</small></div><a class="link-inline" href="/api/ops/backups/download?name=${encodeURIComponent(item.name)}" download>下载备份</a></div>`).join('')||'<div class="empty-state">暂无备份，可点击立即备份。</div>'}</div></section>`;hydrate()}catch(error){const target=document.querySelector('#report-access-panel');if(target)target.innerHTML=`<p class="report-admin-error">${esc(error.message)}</p>`}}
function reportTargetExemptions(item){return (Array.isArray(item.exemptions)?item.exemptions:[]).map(entry=>`<small class="report-goal-exemption">减免 ${esc(entry.date)} · ${opsNumber(entry.quantity)} 件 · ${esc(entry.reason)}</small>`).join('')}
function reportTargetTime(value,end=false){const text=String(value||'');return /^\d{4}-\d{2}-\d{2}$/.test(text)?text+(end?'T23:59':'T00:00'):text}
function reportTargetStatus(item){if(item.complete===true)return `已收录 ${opsNumber(item.actual)} 件 · 已达标`;if(!item.verified)return `已收录 ${opsNumber(item.actual)} 件 · 暂时无法核实是否达标`;return `已发布 ${opsNumber(item.actual)} 件 · 尚差 ${opsNumber(item.shortfall)} 件${item.period_ended?'（周期已结束）':'（进行中）'}`}
async function reportLoadTargets(){try{const result=await api('/ops/targets'),target=document.querySelector('#report-targets-panel');if(!target)return;const summary=result.summary||{};target.innerHTML=`<section class="panel"><div class="panel-header report-admin-header"><span class="panel-title">${icon('calendar')}发布目标</span><button class="primary" data-report-target-new>设置目标</button></div><div class="panel-body"><p class="subtle ops-footnote">可按员工或小组设置一段时间内应发布的作品数量。按发布时间统计，巡检不完整时显示“无法核实”，不会自动判定未完成。请假、休息或临时调整可记录减免。</p><div class="report-target-summary"><span>个人目标 ${opsNumber(summary.employee?.target??0)} 件 · 待核实 ${opsNumber(summary.employee?.unverifiable??0)} 项</span><span>小组目标 ${opsNumber(summary.group?.target??0)} 件 · 待核实 ${opsNumber(summary.group?.unverifiable??0)} 项</span></div>${(result.items||[]).map(item=>`<div class="ops-check-row"><div><b>${esc(item.target_name||item.name||item.target_id)} · ${item.scope==='group'?'小组':'个人'}目标</b><small>${esc(reportTargetTime(item.start_time||item.start).replace('T',' '))} 至 ${esc(reportTargetTime(item.end_time||item.end,true).replace('T',' '))}（北京时间） · 应发布 ${opsNumber(item.quantity)} 件${item.exempt_quantity?' · 已减免 '+opsNumber(item.exempt_quantity)+' 件':''}</small><p>${reportTargetStatus(item)} ${esc(item.note||'')}</p>${reportTargetExemptions(item)}</div><div class="report-admin-actions"><button class="text-button" data-report-target="${esc(item.id)}">编辑</button><button class="text-button" data-report-target-exempt="${esc(item.id)}">记录减免</button></div></div>`).join('')||'<div class="empty-state">尚未设置目标，系统仅展示实际发布和报送数量。</div>'}</div></section>`;reportAdmin.targets=result.items||[];hydrate()}catch(error){const target=document.querySelector('#report-targets-panel');if(target)target.innerHTML=`<p class="report-admin-error">${esc(error.message)}</p>`}}
function reportTargetEditor(id){const item=(reportAdmin.targets||[]).find(t=>t.id===id)||{},p=ops.data.people,today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());opsModal(id?'编辑发布目标':'设置发布目标',`<form id="report-target-form"><div class="form-grid"><div class="field"><label for="report-target-scope">目标范围</label><select id="report-target-scope" name="scope"><option value="employee">员工</option><option value="group" ${item.scope==='group'?'selected':''}>小组</option></select></div><div class="field"><label for="report-target-person">员工 / 小组</label><select id="report-target-person" name="target_id" required></select></div>${opsField('开始时间（北京时间）','start',reportTargetTime(item.start_time||item.start||today),'datetime-local','required step="60"')}${opsField('结束时间（北京时间）','end',reportTargetTime(item.end_time||item.end||today,true),'datetime-local','required step="60"')}${opsField('期间应发布数量','quantity',item.quantity??1,'number','required min="1" max="100000"')}</div><p class="ops-footnote">按作品发布时间（北京时间）统计，包含结束时间所在的一整分钟。原有按日期设置的目标保留全天范围。</p><div class="field"><label for="report-target-note">目标说明</label><textarea id="report-target-note" name="note" maxlength="1000">${esc(item.note||'')}</textarea></div><label class="ops-checkbox"><input type="checkbox" name="enabled" ${item.enabled!==0&&item.enabled!==false?'checked':''}>启用目标</label><p class="ops-form-error" id="report-target-error" role="alert"></p><button class="primary" type="submit">保存目标</button></form>`);const scope=document.querySelector('#report-target-scope'),person=document.querySelector('#report-target-person');function update(){person.innerHTML=opsOpts(scope.value==='group'?reportGroups():p.users.filter(u=>u.role!=='admin'&&u.enabled),'id','name',item.target_id,'选择目标对象')}scope.onchange=update;update();const startInput=document.querySelector('#edit-start'),endInput=document.querySelector('#edit-end');startInput.oninput=()=>{endInput.min=startInput.value};startInput.oninput();document.querySelector('#report-target-form').onsubmit=async event=>{event.preventDefault();const button=event.target.querySelector('button');button.disabled=true;try{const data=Object.fromEntries(new FormData(event.target));data.quantity=Number(data.quantity);data.enabled=event.target.elements.enabled.checked;if(id)data.id=id;await post('/ops/targets',data);document.querySelector('#detail-dialog').close();toast('发布目标已保存');await reportLoadTargets()}catch(error){document.querySelector('#report-target-error').textContent=error.message}finally{button.disabled=false}}}
function reportTargetExempt(id){opsModal('记录目标减免',`<form id="report-target-exempt-form">${opsField('减免日期','date','','date','required')}${opsField('减免作品数量','quantity',1,'number','min="1" max="100000" required')}<div class="field"><label for="report-exempt-reason">原因</label><textarea name="reason" id="report-exempt-reason" required minlength="2" maxlength="1000" placeholder="例如：请假、休息日或临时工作调整"></textarea></div><p class="ops-form-error" id="report-target-error" role="alert"></p><button class="primary" type="submit">保存减免</button></form>`);document.querySelector('#report-target-exempt-form').onsubmit=async event=>{event.preventDefault();try{const data=Object.fromEntries(new FormData(event.target));await post('/ops/targets/exempt',{id,...data,quantity:Number(data.quantity)});document.querySelector('#detail-dialog').close();toast('目标减免已记录');await reportLoadTargets()}catch(error){document.querySelector('#report-target-error').textContent=error.message}}}
document.addEventListener('change',event=>{const box=event.target;if(box.dataset.reportSelect){if(box.checked)reportAdmin.selected.add(box.dataset.reportSelect);else reportAdmin.selected.delete(box.dataset.reportSelect);reportUpdateSelected()}});
document.addEventListener('click',async event=>{const button=event.target.closest('button');if(!button||ops.user?.role!=='admin')return;try{
  if(button.dataset.reportInspectionWorks){opsOpen('works',{binding:button.dataset.reportInspectionWorks});return}
  if(button.dataset.reportFullInspect){button.disabled=true;try{const result=await post('/ops/jobs',{kind:'inspect',target:button.dataset.reportFullInspect,full_scan:true});toast(result.message+'；将从监测开始时间补查历史')}finally{button.disabled=false}}
  if(button.hasAttribute('data-report-bindings-toggle')){ops.bindingsDeleted=!ops.bindingsDeleted;await loadOps()}
  if(button.dataset.reportBindingDelete)reportDeleteBinding(button.dataset.reportBindingDelete);
  if(button.dataset.reportBindingRestore){button.disabled=true;try{const result=await post('/ops/bindings/restore',{id:button.dataset.reportBindingRestore});toast(result.message);await loadOps()}finally{button.disabled=false}}
  if(button.dataset.reportWorkDelete)reportDeleteWork(button.dataset.reportWorkDelete);
  if(button.hasAttribute('data-report-jobs-toggle')){ops.jobsDeleted=!ops.jobsDeleted;await loadOps()}
  if(button.dataset.reportJobDelete)reportDeleteJob(button.dataset.reportJobDelete);
  if(button.dataset.reportJobRestore){button.disabled=true;try{const result=await post('/ops/jobs/restore',{id:button.dataset.reportJobRestore});toast(result.message);await loadOps()}finally{button.disabled=false}}
  if(button.dataset.reportRestore){button.disabled=true;try{const result=await post('/ops/employees/restore',{id:button.dataset.reportRestore});toast(result.message);await loadOps()}finally{button.disabled=false}}
  if(button.hasAttribute('data-report-person-new'))reportEditor('person');if(button.dataset.reportPerson)reportEditor('person',button.dataset.reportPerson);
  if(button.hasAttribute('data-report-dept-new'))reportEditor('dept');if(button.dataset.reportDept)reportEditor('dept',button.dataset.reportDept);
  if(button.hasAttribute('data-report-group-new'))reportEditor('group');if(button.dataset.reportGroup)reportEditor('group',button.dataset.reportGroup);
  if(button.hasAttribute('data-report-import'))reportImport();if(button.hasAttribute('data-report-reload'))await reportLoadQueue();
  if(button.dataset.reportPage){reportAdmin.page+=Number(button.dataset.reportPage);await reportLoadQueue()}
  if(button.dataset.reportDetail)reportItemDetail(button.dataset.reportDetail);
  if(button.dataset.reportReview)reportReview([button.dataset.reportReview],'approve');if(button.dataset.reportReject)reportReview([button.dataset.reportReject],'reject');if(button.dataset.reportRetry)await reportDoReview({ids:[button.dataset.reportRetry],action:'retry'});
  if(button.dataset.reportBatch)reportReview([...reportAdmin.selected],button.dataset.reportBatch);
  if(button.dataset.reportItemDelete)reportDeleteReports([button.dataset.reportItemDelete]);
  if(button.hasAttribute('data-report-delete-selected'))reportDeleteReports([...reportAdmin.selected]);
  if(button.hasAttribute('data-report-reset-filters')){reportAdmin.filters={};reportAdmin.page=1;opsOpen('audit',{})}
  if(button.hasAttribute('data-overview-works'))opsOpen('works',{...ops.filters});
  if(button.dataset.reportOpenState){const {department,employee,group}=ops.filters;reportAdmin.filters={state:button.dataset.reportOpenState,department:department||'',employee:employee||'',group:group||''};reportAdmin.page=1;opsOpen('audit',{})}
  if(button.dataset.reportCopy){try{await navigator.clipboard.writeText(button.dataset.reportCopy);toast('地址已复制')}catch{opsModal('员工报送地址',`<div class="field"><label for="report-copy-url">复制下面地址发送给员工</label><input id="report-copy-url" readonly value="${esc(button.dataset.reportCopy)}"></div>`);document.querySelector('#report-copy-url').select()}}
  if(button.hasAttribute('data-report-backup')){button.disabled=true;try{const result=await post('/ops/backups',{});toast(result.message||'备份已生成');await reportLoadAccess()}finally{button.disabled=false}}
  if(button.hasAttribute('data-report-target-new'))reportTargetEditor();if(button.dataset.reportTarget)reportTargetEditor(button.dataset.reportTarget);if(button.dataset.reportTargetExempt)reportTargetExempt(button.dataset.reportTargetExempt);
}catch(error){toast(error.message)}});
document.addEventListener('DOMContentLoaded',()=>{document.querySelector('#help-button').onclick=()=>opsModal('部门作品报送流程','<div class="detail-list"><p>1. 员工填写姓名、部门和小组，报送时自动建立名册，无需网站账号。</p><p>2. 员工粘贴作品链接，可在旁边扫码登录抖音核验发布账号。</p><p>3. 登录账号与作品作者一致时自动通过，否则进入报送核查；特殊情况可通过回执补充备注。</p><p>4. 在系统设置配置采集连接和自动巡检，只有完整读取发布列表后才判断漏报。</p><p>5. 按部门、员工、小组、时间筛选作品，导出 Excel。局域网地址和 SQLite 备份在系统设置查看。</p></div>')});

// The business workspace has its own guide; do not show collection-tool instructions.
window.addEventListener('DOMContentLoaded',()=>{document.querySelector('#help-button').onclick=()=>{opsModal('网站使用帮助',`<div class="detail-list"><p>员工填写部门、小组、姓名，至少完成一个抖音账号核验后报送作品；可核验多个账号。管理员在每日报送进度查看有效完成与差额，在报送核查处理待核实记录。</p><p>完成数按作品发布日期、责任人和作品 ID 去重，补交昨天的作品不计今天；系统不再自动巡检主页。以下文档已同步至 2026.10.31 当前版本。</p><p><a class="link-inline" href="/help/usage.html" target="_blank" rel="noreferrer">操作说明 ↗</a></p><p><a class="link-inline" href="/help/developer.html" target="_blank" rel="noreferrer">开发与部署文档 ↗</a></p><p><a class="link-inline" href="/help/verification.html" target="_blank" rel="noreferrer">版本验证记录 ↗</a></p></div>`)};});

/* Daily requirements are effective-dated; each save appends a version. */
function reportToday(){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function reportSubmissionRules(){return '<div id="daily-rules-panel"><section class="panel"><div class="panel-body">正在读取每日要求…</div></section></div>'+`<details class="daily-timing-rules"><summary>发布后报送时限与采集失败重试</summary>${reportTimingRules()}</details>`}
function reportWeekdays(days){return days?.length===7?'每天':(days||[]).map(i=>['周一','周二','周三','周四','周五','周六','周日'][i]).join('、')}
async function reportLoadDailyRules(){
  const target=document.querySelector('#daily-rules-panel');if(!target)return;
  try{
    const data=await api('/ops/daily-targets'),rule=data.default,history=data.history||[];
    if(state.page!=='opssettings'||ops.settingsTab!=='rules'||!target.isConnected)return;
    target.innerHTML=`<section class="panel"><div class="panel-header"><span class="panel-title">每日报送要求</span><span class="subtle">北京时间 · 按作品发布日期计算</span></div><form class="panel-body" id="daily-default-form"><div class="daily-rule-grid"><div class="field"><label for="daily-quantity">统一要求（条 / 人 / 天）</label><input id="daily-quantity" name="quantity" type="number" min="0" max="1000" value="${rule.base_quantity??rule.quantity??2}" required></div><div class="field"><label for="daily-cutoff">每日截止时间</label><input type="time" step="60" id="daily-cutoff" name="cutoff" value="${esc(rule.cutoff||'23:59')}" required></div><div class="field"><label for="daily-start">本次设置从哪天生效</label><input type="date" id="daily-start" name="start_day" value="${reportToday()}" required></div></div><fieldset class="daily-weekdays"><legend>每周执行日</legend>${['周一','周二','周三','周四','周五','周六','周日'].map((name,i)=>`<label><input type="checkbox" name="weekdays" value="${i}" ${(rule.weekdays||[0,1,2,3,4,5,6]).includes(i)?'checked':''}>${name}</label>`).join('')}</fieldset><p class="subtle ops-footnote">${rule.configured?`今天的统一要求：${rule.quantity} 条 / 人，${esc(reportWeekdays(rule.weekdays))}，${esc(rule.cutoff)} 截止。`:'尚未启用每日目标。保存后从所选日期开始执行。'}个人可单独设条数；个人常规要求沿用统一执行日及截止时间，单日调整优先。0 条表示免报。</p><div class="daily-rule-example">例如要求 3 条，审核通过 2 条、待核实 1 条：有效完成 2 / 3，还差 1 条。重复链接不加条数；补交昨天的作品归入昨天。</div><p class="ops-form-error" id="daily-default-error" role="alert"></p><div class="result-actions"><button class="primary" type="submit">保存统一要求</button><button class="secondary" type="button" data-daily-batch>批量设置个人要求</button><button class="text-button" type="button" data-daily-view>查看今日进度 ↗</button></div></form></section><section class="panel"><div class="panel-header"><span class="panel-title">员工每日要求</span><small class="subtle">展示今天生效的条数</small></div><div class="ops-table-wrap"><table class="ops-table"><thead><tr><th>员工</th><th>今日要求</th><th>来源 / 原因</th><th>操作</th></tr></thead><tbody>${data.employees.map(u=>`<tr><td>${esc(u.name)}<small>${esc(u.employee_code)}${u.enabled?'':' · 已停用'}</small></td><td>${u.target.configured?u.target.quantity+' 条':'未设置'}</td><td>${esc(u.target.source)}${u.target.note?`<small>${esc(u.target.note)}</small>`:''}</td><td><button class="text-button" data-daily-employee="${esc(u.id)}" ${u.enabled?'':'disabled'}>设置个人要求</button></td></tr>`).join('')||'<tr><td colspan="4"><div class="empty-state">先到部门与人员补齐员工名册。</div></td></tr>'}</tbody></table></div></section><details class="daily-history"><summary>查看规则变更记录（含尚未生效的设置）</summary><section class="panel"><div class="ops-table-wrap"><table class="ops-table"><thead><tr><th>生效日期 / 范围</th><th>要求</th><th>执行日 / 截止时间</th><th>说明</th></tr></thead><tbody>${history.map(h=>`<tr><td>${esc(h.start_day)}<small>${esc(h.name)} · ${h.kind==='day'?'仅当天':'从此日起'}</small></td><td>${h.quantity===null?'恢复继承':h.quantity+' 条 / 天'}</td><td>${h.employee_id?'沿用统一设置':esc(reportWeekdays(h.weekdays))+' · '+esc(h.cutoff)}</td><td>${esc(h.note||'—')}</td></tr>`).join('')||'<tr><td colspan="4">暂无变更</td></tr>'}</tbody></table></div></section></details>`;
    document.querySelector('#daily-default-form').onsubmit=async e=>{e.preventDefault();const form=e.target,button=form.querySelector('[type=submit]');button.disabled=true;try{await post('/ops/daily-targets',{scope:'default',kind:'recurring',quantity:form.elements.quantity.value,cutoff:form.elements.cutoff.value,start_day:form.elements.start_day.value,weekdays:[...form.querySelectorAll('[name=weekdays]:checked')].map(e=>Number(e.value))});toast('统一要求已保存');await loadOps()}catch(error){document.querySelector('#daily-default-error').textContent=error.message}finally{button.disabled=false}};
  }catch(error){target.innerHTML=`<section class="panel"><div class="panel-body report-admin-error">${esc(error.message)}</div></section>`}
}
async function reportDailyEditor(employeeId=''){
  try{
    const day=state.page==='unreported'?ops.data.progress.date:reportToday();
    const data=await api('/ops/daily-targets?'+new URLSearchParams({date:day})),employees=data.employees.filter(u=>u.enabled),person=employees.find(u=>u.id===employeeId);
    if(employeeId&&!person)return toast('员工已停用或不存在，请刷新名册。');
    const quota=person?.target.personal_quantity??data.default.base_quantity??data.default.quantity??2;
    opsModal(person?'设置个人每日报送要求':'批量设置每日报送要求',`<form id="daily-person-form">${person?`<p class="daily-editor-person"><b>${esc(person.name)}</b> · ${esc(person.employee_code)}<small>所选日期 ${esc(day)}：${person.target.quantity??'未设置'} 条 · ${esc(person.target.source)}</small></p>`:`<fieldset class="daily-employee-options"><legend>选择员工</legend><label class="daily-select-all"><input type="checkbox" id="daily-select-all"> 全选启用员工</label>${employees.map(u=>`<label><input name="employees" type="checkbox" value="${esc(u.id)}">${esc(u.name)} <small>${esc(u.employee_code)}</small></label>`).join('')||'<p>暂无启用员工</p>'}</fieldset>`}<div class="field"><label for="daily-person-kind">设置范围</label><select id="daily-person-kind" name="kind"><option value="recurring">从生效日起，每个执行日</option><option value="day">仅调整指定一天</option></select></div><div class="daily-rule-grid"><div class="field"><label for="daily-person-start">生效 / 指定日期</label><input id="daily-person-start" name="start_day" type="date" value="${esc(day)}" required></div><div class="field"><label for="daily-person-quantity">每日条数（0 表示免报）</label><input id="daily-person-quantity" name="quantity" type="number" min="0" max="1000" value="${quota}" required></div></div><label class="ops-checkbox"><input name="inherit" type="checkbox">取消此层个人设置，恢复继承</label><div class="field"><label for="daily-person-note">原因 / 说明（单日调整必填）</label><textarea id="daily-person-note" name="note" maxlength="500" rows="3" placeholder="例如：负责三个账号，每日要求 3 条；或当日请假调整为 0 条"></textarea></div><p class="subtle ops-footnote">统一执行日：${esc(reportWeekdays(data.default.weekdays))}；每日 ${esc(data.default.cutoff)} 截止。个人常规要求沿用这些设置；仅一天的安排优先，可单独安排休息日。保存保留旧规则；生效日之前的要求不变。已设置当日免报时，需在进度页取消免报后才执行条数要求。</p><p class="ops-form-error" id="daily-person-error" role="alert"></p><button class="primary" type="submit">保存要求</button></form>`);
    const form=document.querySelector('#daily-person-form');
    form.elements.inherit.onchange=()=>{form.elements.quantity.disabled=form.elements.inherit.checked};
    form.elements.kind.onchange=()=>{form.elements.note.required=form.elements.kind.value==='day'};
    document.querySelector('#daily-select-all')?.addEventListener('change',e=>form.querySelectorAll('[name=employees]').forEach(input=>input.checked=e.target.checked));
    form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;try{await post('/ops/daily-targets',{scope:'employee',employees:person?[person.id]:[...form.querySelectorAll('[name=employees]:checked')].map(input=>input.value),kind:form.elements.kind.value,start_day:form.elements.start_day.value,quantity:form.elements.quantity.value,inherit:form.elements.inherit.checked,note:form.elements.note.value});document.querySelector('#detail-dialog').close();await loadOps();toast('个人每日报送要求已保存')}catch(error){document.querySelector('#daily-person-error').textContent=error.message}finally{button.disabled=false}};
  }catch(error){toast(error.message)}
}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||ops.user?.role!=='admin')return;
  if(b.hasAttribute('data-daily-open-rules')){ops.settingsTab='rules';if(state.page==='opssettings')loadOps();else navigate('opssettings')}
  if(b.dataset.dailyEmployee)reportDailyEditor(b.dataset.dailyEmployee);
  if(b.hasAttribute('data-daily-batch'))reportDailyEditor();
  if(b.hasAttribute('data-daily-view'))opsOpen('unreported',{date:reportToday(),status:'all'});
  if(b.dataset.dailyWorks){const day=ops.data.progress.date;opsOpen('works',{employee:b.dataset.dailyWorks,start:day+'T00:00',end:day+'T23:59'})}
});
